// Type: Repository.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Repository {
    pub forge: u16,
    pub repository: u32,
}

// Record: Repository.
impl Record for Repository {
    type Limits = Limits;
    const TAIL: Path = paths::REPOSITORY_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::write(field::U16, &self.forge, limits, out, paths::REPOSITORY_FORGE)?;
        field::write(field::U32, &self.repository, limits, out, paths::REPOSITORY_REPOSITORY)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        Ok(Self {
            forge: field::read(field::U16, limits, reader, paths::REPOSITORY_FORGE)?,
            repository: field::read(field::U32, limits, reader, paths::REPOSITORY_REPOSITORY)?,
        })
    }
}

