// Type: AnswerName.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct AnswerName {
    pub name: Box<[u8]>,
}

// Record: AnswerName.
impl Record for AnswerName {
    type Limits = Limits;
    const TAIL: Path = paths::ANSWER_NAME_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 10)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 10)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::write(field::Bytes { limit: limits.answer_name_name.min(CEILINGS.answer_name_name) }, &self.name, limits, out, paths::ANSWER_NAME_NAME)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        Ok(Self {
            name: field::read(field::Bytes { limit: limits.answer_name_name.min(CEILINGS.answer_name_name) }, limits, reader, paths::ANSWER_NAME_NAME)?,
        })
    }
}

