// Type: Error.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Error {
    Unavailable,
    Timeout,
    RateLimited(RateLimited),
    Forbidden,
    Missing,
    MissingJob,
    TooLarge(Excess),
    Empty,
    Full,
    Exists,
    NothingToMerge,
    Closed,
    Stale,
    Conflict,
    Protected,
    Refused,
    InvalidAnswer,
    Busy,
    NotInstalled,
    BaseMoved(BaseMoved),
}

// Record: Error.
impl Record for Error {
    type Limits = Limits;
    const TAIL: Path = paths::ERROR_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 297)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 297)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Unavailable => field::put(out, &[0], paths::ERROR_TAG),
            Self::Timeout => field::put(out, &[1], paths::ERROR_TAG),
            Self::RateLimited(value) => { field::put(out, &[2], paths::ERROR_TAG)?; value.write(limits, out) },
            Self::Forbidden => field::put(out, &[3], paths::ERROR_TAG),
            Self::Missing => field::put(out, &[4], paths::ERROR_TAG),
            Self::MissingJob => field::put(out, &[5], paths::ERROR_TAG),
            Self::TooLarge(value) => { field::put(out, &[6], paths::ERROR_TAG)?; value.write(limits, out) },
            Self::Empty => field::put(out, &[7], paths::ERROR_TAG),
            Self::Full => field::put(out, &[8], paths::ERROR_TAG),
            Self::Exists => field::put(out, &[9], paths::ERROR_TAG),
            Self::NothingToMerge => field::put(out, &[10], paths::ERROR_TAG),
            Self::Closed => field::put(out, &[11], paths::ERROR_TAG),
            Self::Stale => field::put(out, &[12], paths::ERROR_TAG),
            Self::Conflict => field::put(out, &[13], paths::ERROR_TAG),
            Self::Protected => field::put(out, &[14], paths::ERROR_TAG),
            Self::Refused => field::put(out, &[15], paths::ERROR_TAG),
            Self::InvalidAnswer => field::put(out, &[16], paths::ERROR_TAG),
            Self::Busy => field::put(out, &[17], paths::ERROR_TAG),
            Self::NotInstalled => field::put(out, &[18], paths::ERROR_TAG),
            Self::BaseMoved(value) => { field::put(out, &[19], paths::ERROR_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::ERROR_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Unavailable),
            1 => Ok(Self::Timeout),
            2 => Ok(Self::RateLimited(RateLimited::read(limits, reader)?)),
            3 => Ok(Self::Forbidden),
            4 => Ok(Self::Missing),
            5 => Ok(Self::MissingJob),
            6 => Ok(Self::TooLarge(Excess::read(limits, reader)?)),
            7 => Ok(Self::Empty),
            8 => Ok(Self::Full),
            9 => Ok(Self::Exists),
            10 => Ok(Self::NothingToMerge),
            11 => Ok(Self::Closed),
            12 => Ok(Self::Stale),
            13 => Ok(Self::Conflict),
            14 => Ok(Self::Protected),
            15 => Ok(Self::Refused),
            16 => Ok(Self::InvalidAnswer),
            17 => Ok(Self::Busy),
            18 => Ok(Self::NotInstalled),
            19 => Ok(Self::BaseMoved(BaseMoved::read(limits, reader)?)),
            20..=u8::MAX => Err(Problem { path: paths::ERROR_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

