// Type: Outcome.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Outcome {
    Made(OutcomeMade),
    Failed(ErrorValue),
    Raced(OutcomeRaced),
    Uncertain,
    Held,
    Withdrawn,
    Queued,
}

// Record: Outcome.
impl Record for Outcome {
    type Limits = Limits;
    const TAIL: Path = paths::OUTCOME_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 308)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 308)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Made(value) => { field::put(out, &[0], paths::OUTCOME_TAG)?; value.write(limits, out) },
            Self::Failed(value) => { field::put(out, &[1], paths::OUTCOME_TAG)?; value.write(limits, out) },
            Self::Raced(value) => { field::put(out, &[2], paths::OUTCOME_TAG)?; value.write(limits, out) },
            Self::Uncertain => field::put(out, &[3], paths::OUTCOME_TAG),
            Self::Held => field::put(out, &[4], paths::OUTCOME_TAG),
            Self::Withdrawn => field::put(out, &[5], paths::OUTCOME_TAG),
            Self::Queued => field::put(out, &[6], paths::OUTCOME_TAG),
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::OUTCOME_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Made(OutcomeMade::read(limits, reader)?)),
            1 => Ok(Self::Failed(ErrorValue::read(limits, reader)?)),
            2 => Ok(Self::Raced(OutcomeRaced::read(limits, reader)?)),
            3 => Ok(Self::Uncertain),
            4 => Ok(Self::Held),
            5 => Ok(Self::Withdrawn),
            6 => Ok(Self::Queued),
            7..=u8::MAX => Err(Problem { path: paths::OUTCOME_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

