// Type: Answer.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Answer {
    Items(ItemsAnswer),
    Item(ItemAnswer),
    Pull(Pull),
    Reviews(ReviewsAnswer),
    Statuses(StatusesAnswer),
    Remarks(RemarksAnswer),
    Commit(Commit),
    Branches(BranchesAnswer),
    PullFiles(PullFilesAnswer),
    Compare(CompareAnswer),
    Checks(ChecksAnswer),
    Job(JobAnswer),
    File(FileAnswer),
    Protection(ProtectionAnswer),
    Settings(Settings),
    Collaborators(CollaboratorsAnswer),
    Permission(PermissionValue),
    Created(Number),
    Commented(Number),
    Reviewed(Number),
    Merged(Commit),
    Branch(BranchCreationValue),
    Done,
    Located(Located),
    Queued,
    Directory(DirectoryAnswer),
}

// Record: Answer.
impl Record for Answer {
    type Limits = Limits;
    const TAIL: Path = paths::ANSWER_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 455)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 455)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Items(value) => { field::put(out, &[0], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Item(value) => { field::put(out, &[1], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Pull(value) => { field::put(out, &[2], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Reviews(value) => { field::put(out, &[3], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Statuses(value) => { field::put(out, &[4], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Remarks(value) => { field::put(out, &[5], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Commit(value) => { field::put(out, &[6], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Branches(value) => { field::put(out, &[7], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::PullFiles(value) => { field::put(out, &[8], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Compare(value) => { field::put(out, &[9], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Checks(value) => { field::put(out, &[10], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Job(value) => { field::put(out, &[11], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::File(value) => { field::put(out, &[12], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Protection(value) => { field::put(out, &[13], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Settings(value) => { field::put(out, &[14], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Collaborators(value) => { field::put(out, &[15], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Permission(value) => { field::put(out, &[16], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Created(value) => { field::put(out, &[17], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Commented(value) => { field::put(out, &[18], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Reviewed(value) => { field::put(out, &[19], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Merged(value) => { field::put(out, &[20], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Branch(value) => { field::put(out, &[21], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Done => field::put(out, &[22], paths::ANSWER_TAG),
            Self::Located(value) => { field::put(out, &[23], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Queued => field::put(out, &[24], paths::ANSWER_TAG),
            Self::Directory(value) => { field::put(out, &[25], paths::ANSWER_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::ANSWER_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Items(ItemsAnswer::read(limits, reader)?)),
            1 => Ok(Self::Item(ItemAnswer::read(limits, reader)?)),
            2 => Ok(Self::Pull(Pull::read(limits, reader)?)),
            3 => Ok(Self::Reviews(ReviewsAnswer::read(limits, reader)?)),
            4 => Ok(Self::Statuses(StatusesAnswer::read(limits, reader)?)),
            5 => Ok(Self::Remarks(RemarksAnswer::read(limits, reader)?)),
            6 => Ok(Self::Commit(Commit::read(limits, reader)?)),
            7 => Ok(Self::Branches(BranchesAnswer::read(limits, reader)?)),
            8 => Ok(Self::PullFiles(PullFilesAnswer::read(limits, reader)?)),
            9 => Ok(Self::Compare(CompareAnswer::read(limits, reader)?)),
            10 => Ok(Self::Checks(ChecksAnswer::read(limits, reader)?)),
            11 => Ok(Self::Job(JobAnswer::read(limits, reader)?)),
            12 => Ok(Self::File(FileAnswer::read(limits, reader)?)),
            13 => Ok(Self::Protection(ProtectionAnswer::read(limits, reader)?)),
            14 => Ok(Self::Settings(Settings::read(limits, reader)?)),
            15 => Ok(Self::Collaborators(CollaboratorsAnswer::read(limits, reader)?)),
            16 => Ok(Self::Permission(PermissionValue::read(limits, reader)?)),
            17 => Ok(Self::Created(Number::read(limits, reader)?)),
            18 => Ok(Self::Commented(Number::read(limits, reader)?)),
            19 => Ok(Self::Reviewed(Number::read(limits, reader)?)),
            20 => Ok(Self::Merged(Commit::read(limits, reader)?)),
            21 => Ok(Self::Branch(BranchCreationValue::read(limits, reader)?)),
            22 => Ok(Self::Done),
            23 => Ok(Self::Located(Located::read(limits, reader)?)),
            24 => Ok(Self::Queued),
            25 => Ok(Self::Directory(DirectoryAnswer::read(limits, reader)?)),
            26..=u8::MAX => Err(Problem { path: paths::ANSWER_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

