// Type: Early.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Early {
    None,
    Started(EarlyHeads),
    Spent(EarlyHeads),
}

// Record: Early.
impl Record for Early {
    type Limits = Limits;
    const TAIL: Path = paths::EARLY_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 684)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 684)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::None => field::put(out, &[0], paths::EARLY_TAG),
            Self::Started(value) => { field::put(out, &[1], paths::EARLY_TAG)?; value.write(limits, out) },
            Self::Spent(value) => { field::put(out, &[2], paths::EARLY_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::EARLY_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::None),
            1 => Ok(Self::Started(EarlyHeads::read(limits, reader)?)),
            2 => Ok(Self::Spent(EarlyHeads::read(limits, reader)?)),
            3..=u8::MAX => Err(Problem { path: paths::EARLY_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

