// Type: MilestoneKey.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum MilestoneKey {
    Lifecycle(Lifecycle),
    TaskRevision(TaskRevision),
    PlanAccepted,
    Revision(Number),
    ChangeLanded(Number),
    ChangeHeld(Number),
    Report(Number),
    Finished,
}

// Record: MilestoneKey.
impl Record for MilestoneKey {
    type Limits = Limits;
    const TAIL: Path = paths::MILESTONE_KEY_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 807)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 807)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Lifecycle(value) => { field::put(out, &[0], paths::MILESTONE_KEY_TAG)?; value.write(limits, out) },
            Self::TaskRevision(value) => { field::put(out, &[1], paths::MILESTONE_KEY_TAG)?; value.write(limits, out) },
            Self::PlanAccepted => field::put(out, &[2], paths::MILESTONE_KEY_TAG),
            Self::Revision(value) => { field::put(out, &[3], paths::MILESTONE_KEY_TAG)?; value.write(limits, out) },
            Self::ChangeLanded(value) => { field::put(out, &[4], paths::MILESTONE_KEY_TAG)?; value.write(limits, out) },
            Self::ChangeHeld(value) => { field::put(out, &[5], paths::MILESTONE_KEY_TAG)?; value.write(limits, out) },
            Self::Report(value) => { field::put(out, &[6], paths::MILESTONE_KEY_TAG)?; value.write(limits, out) },
            Self::Finished => field::put(out, &[7], paths::MILESTONE_KEY_TAG),
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::MILESTONE_KEY_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Lifecycle(Lifecycle::read(limits, reader)?)),
            1 => Ok(Self::TaskRevision(TaskRevision::read(limits, reader)?)),
            2 => Ok(Self::PlanAccepted),
            3 => Ok(Self::Revision(Number::read(limits, reader)?)),
            4 => Ok(Self::ChangeLanded(Number::read(limits, reader)?)),
            5 => Ok(Self::ChangeHeld(Number::read(limits, reader)?)),
            6 => Ok(Self::Report(Number::read(limits, reader)?)),
            7 => Ok(Self::Finished),
            8..=u8::MAX => Err(Problem { path: paths::MILESTONE_KEY_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

