// Type: LandingPlace.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum LandingPlace {
    Waiting,
    Preparing,
    Proving,
    Proved(LandingAt),
    Turn(LandingAt),
    Landed,
    Cancelled,
}

// Record: LandingPlace.
impl Record for LandingPlace {
    type Limits = Limits;
    const TAIL: Path = paths::LANDING_PLACE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 955)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 955)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Waiting => field::put(out, &[0], paths::LANDING_PLACE_TAG),
            Self::Preparing => field::put(out, &[1], paths::LANDING_PLACE_TAG),
            Self::Proving => field::put(out, &[2], paths::LANDING_PLACE_TAG),
            Self::Proved(value) => { field::put(out, &[3], paths::LANDING_PLACE_TAG)?; value.write(limits, out) },
            Self::Turn(value) => { field::put(out, &[4], paths::LANDING_PLACE_TAG)?; value.write(limits, out) },
            Self::Landed => field::put(out, &[5], paths::LANDING_PLACE_TAG),
            Self::Cancelled => field::put(out, &[6], paths::LANDING_PLACE_TAG),
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::LANDING_PLACE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Waiting),
            1 => Ok(Self::Preparing),
            2 => Ok(Self::Proving),
            3 => Ok(Self::Proved(LandingAt::read(limits, reader)?)),
            4 => Ok(Self::Turn(LandingAt::read(limits, reader)?)),
            5 => Ok(Self::Landed),
            6 => Ok(Self::Cancelled),
            7..=u8::MAX => Err(Problem { path: paths::LANDING_PLACE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

