// Type: Failures.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Failures {
    Tests(FailedTests),
    Many,
}

// Record: Failures.
impl Record for Failures {
    type Limits = Limits;
    const TAIL: Path = paths::FAILURES_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1189)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1189)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Tests(value) => { field::put(out, &[0], paths::FAILURES_TAG)?; value.write(limits, out) },
            Self::Many => field::put(out, &[1], paths::FAILURES_TAG),
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::FAILURES_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Tests(FailedTests::read(limits, reader)?)),
            1 => Ok(Self::Many),
            2..=u8::MAX => Err(Problem { path: paths::FAILURES_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

