// Type: ReceiptReport.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ReceiptReport {
    Unset,
    Unread,
    Many(ReceiptMany),
    Tests(ReceiptTests),
}

// Record: ReceiptReport.
impl Record for ReceiptReport {
    type Limits = Limits;
    const TAIL: Path = paths::RECEIPT_REPORT_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1295)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1295)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Unset => field::put(out, &[0], paths::RECEIPT_REPORT_TAG),
            Self::Unread => field::put(out, &[1], paths::RECEIPT_REPORT_TAG),
            Self::Many(value) => { field::put(out, &[2], paths::RECEIPT_REPORT_TAG)?; value.write(limits, out) },
            Self::Tests(value) => { field::put(out, &[3], paths::RECEIPT_REPORT_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::RECEIPT_REPORT_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Unset),
            1 => Ok(Self::Unread),
            2 => Ok(Self::Many(ReceiptMany::read(limits, reader)?)),
            3 => Ok(Self::Tests(ReceiptTests::read(limits, reader)?)),
            4..=u8::MAX => Err(Problem { path: paths::RECEIPT_REPORT_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

