// Type: ClassSubject.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ClassSubject {
    Kind(ReachKindOf),
    Set(ReachSet),
}

// Record: ClassSubject.
impl Record for ClassSubject {
    type Limits = Limits;
    const TAIL: Path = paths::CLASS_SUBJECT_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1501)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1501)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Kind(value) => { field::put(out, &[0], paths::CLASS_SUBJECT_TAG)?; value.write(limits, out) },
            Self::Set(value) => { field::put(out, &[1], paths::CLASS_SUBJECT_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::CLASS_SUBJECT_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Kind(ReachKindOf::read(limits, reader)?)),
            1 => Ok(Self::Set(ReachSet::read(limits, reader)?)),
            2..=u8::MAX => Err(Problem { path: paths::CLASS_SUBJECT_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

