// Type: LoggedVerdict.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum LoggedVerdict {
    Verifying,
    Cleared(LoggedCleared),
    Red(LoggedRed),
}

// Record: LoggedVerdict.
impl Record for LoggedVerdict {
    type Limits = Limits;
    const TAIL: Path = paths::LOGGED_VERDICT_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1591)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1591)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Verifying => field::put(out, &[0], paths::LOGGED_VERDICT_TAG),
            Self::Cleared(value) => { field::put(out, &[1], paths::LOGGED_VERDICT_TAG)?; value.write(limits, out) },
            Self::Red(value) => { field::put(out, &[2], paths::LOGGED_VERDICT_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::LOGGED_VERDICT_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Verifying),
            1 => Ok(Self::Cleared(LoggedCleared::read(limits, reader)?)),
            2 => Ok(Self::Red(LoggedRed::read(limits, reader)?)),
            3..=u8::MAX => Err(Problem { path: paths::LOGGED_VERDICT_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

