// Type: ClosingStep.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ClosingStep {
    Close,
    Land,
}

// Record: ClosingStep.
impl Record for ClosingStep {
    type Limits = Limits;
    const TAIL: Path = paths::CLOSING_STEP_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1679)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1679)?.decoded)
    }

    fn write(&self, _limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Close => field::put(out, &[0], paths::CLOSING_STEP_TAG),
            Self::Land => field::put(out, &[1], paths::CLOSING_STEP_TAG),
        }
    }

    fn read(_limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::CLOSING_STEP_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Close),
            1 => Ok(Self::Land),
            2..=u8::MAX => Err(Problem { path: paths::CLOSING_STEP_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

