// Type: ClosingSelectionProgress.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ClosingSelectionProgress {
    Pull,
    Checks,
    Jobs(ClosingJobs),
    Done(ClosingLine),
}

// Record: ClosingSelectionProgress.
impl Record for ClosingSelectionProgress {
    type Limits = Limits;
    const TAIL: Path = paths::CLOSING_SELECTION_PROGRESS_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1693)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1693)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Pull => field::put(out, &[0], paths::CLOSING_SELECTION_PROGRESS_TAG),
            Self::Checks => field::put(out, &[1], paths::CLOSING_SELECTION_PROGRESS_TAG),
            Self::Jobs(value) => { field::put(out, &[2], paths::CLOSING_SELECTION_PROGRESS_TAG)?; value.write(limits, out) },
            Self::Done(value) => { field::put(out, &[3], paths::CLOSING_SELECTION_PROGRESS_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::CLOSING_SELECTION_PROGRESS_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Pull),
            1 => Ok(Self::Checks),
            2 => Ok(Self::Jobs(ClosingJobs::read(limits, reader)?)),
            3 => Ok(Self::Done(ClosingLine::read(limits, reader)?)),
            4..=u8::MAX => Err(Problem { path: paths::CLOSING_SELECTION_PROGRESS_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

