// Type: ClosingStands.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ClosingStands {
    Taken,
    Asked(ClosingAsked),
}

// Record: ClosingStands.
impl Record for ClosingStands {
    type Limits = Limits;
    const TAIL: Path = paths::CLOSING_STANDS_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1702)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1702)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Taken => field::put(out, &[0], paths::CLOSING_STANDS_TAG),
            Self::Asked(value) => { field::put(out, &[1], paths::CLOSING_STANDS_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::CLOSING_STANDS_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Taken),
            1 => Ok(Self::Asked(ClosingAsked::read(limits, reader)?)),
            2..=u8::MAX => Err(Problem { path: paths::CLOSING_STANDS_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

