// Type: FollowState.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum FollowState {
    NotMade,
    WaitsWord,
    HeldByOwner(FollowReason),
    WaitsFor(Number),
    Producing,
    Held(FollowReason),
    Ended(FollowReason),
}

// Record: FollowState.
impl Record for FollowState {
    type Limits = Limits;
    const TAIL: Path = paths::FOLLOW_STATE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1754)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1754)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::NotMade => field::put(out, &[0], paths::FOLLOW_STATE_TAG),
            Self::WaitsWord => field::put(out, &[1], paths::FOLLOW_STATE_TAG),
            Self::HeldByOwner(value) => { field::put(out, &[2], paths::FOLLOW_STATE_TAG)?; value.write(limits, out) },
            Self::WaitsFor(value) => { field::put(out, &[3], paths::FOLLOW_STATE_TAG)?; value.write(limits, out) },
            Self::Producing => field::put(out, &[4], paths::FOLLOW_STATE_TAG),
            Self::Held(value) => { field::put(out, &[5], paths::FOLLOW_STATE_TAG)?; value.write(limits, out) },
            Self::Ended(value) => { field::put(out, &[6], paths::FOLLOW_STATE_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::FOLLOW_STATE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::NotMade),
            1 => Ok(Self::WaitsWord),
            2 => Ok(Self::HeldByOwner(FollowReason::read(limits, reader)?)),
            3 => Ok(Self::WaitsFor(Number::read(limits, reader)?)),
            4 => Ok(Self::Producing),
            5 => Ok(Self::Held(FollowReason::read(limits, reader)?)),
            6 => Ok(Self::Ended(FollowReason::read(limits, reader)?)),
            7..=u8::MAX => Err(Problem { path: paths::FOLLOW_STATE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

