// Type: FollowVerdict.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum FollowVerdict {
    Passed,
    Failing(FollowFailing),
    Many,
}

// Record: FollowVerdict.
impl Record for FollowVerdict {
    type Limits = Limits;
    const TAIL: Path = paths::FOLLOW_VERDICT_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1777)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1777)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Passed => field::put(out, &[0], paths::FOLLOW_VERDICT_TAG),
            Self::Failing(value) => { field::put(out, &[1], paths::FOLLOW_VERDICT_TAG)?; value.write(limits, out) },
            Self::Many => field::put(out, &[2], paths::FOLLOW_VERDICT_TAG),
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::FOLLOW_VERDICT_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Passed),
            1 => Ok(Self::Failing(FollowFailing::read(limits, reader)?)),
            2 => Ok(Self::Many),
            3..=u8::MAX => Err(Problem { path: paths::FOLLOW_VERDICT_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

