pub enum Topic {
    Landings(LandingsTopic),
    Ci(CiTopic),
    Pull(NumberTopic),
    Participation(NumberTopic),
    Findings(FindingsTopic),
}

// Record: Topic.
impl Record for Topic {
    type Limits = Limits;
    const TAIL: Path = paths::TOPIC_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2026)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2026)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Landings(value) => { field::put(out, &[0], paths::TOPIC_TAG)?; value.write(limits, out) },
            Self::Ci(value) => { field::put(out, &[1], paths::TOPIC_TAG)?; value.write(limits, out) },
            Self::Pull(value) => { field::put(out, &[2], paths::TOPIC_TAG)?; value.write(limits, out) },
            Self::Participation(value) => { field::put(out, &[3], paths::TOPIC_TAG)?; value.write(limits, out) },
            Self::Findings(value) => { field::put(out, &[4], paths::TOPIC_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::TOPIC_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Landings(LandingsTopic::read(limits, reader)?)),
            1 => Ok(Self::Ci(CiTopic::read(limits, reader)?)),
            2 => Ok(Self::Pull(NumberTopic::read(limits, reader)?)),
            3 => Ok(Self::Participation(NumberTopic::read(limits, reader)?)),
            4 => Ok(Self::Findings(FindingsTopic::read(limits, reader)?)),
            5..=u8::MAX => Err(Problem { path: paths::TOPIC_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

