        field::write(field::Sequence { limit: limits.subscriber_paths.min(CEILINGS.subscriber_paths), minimum: 4, item: field::Bytes { limit: limits.subscriber_paths_item.min(CEILINGS.subscriber_paths_item) } }, &self.paths, limits, out, paths::SUBSCRIBER_PATHS)?;
