// Type: FindingRefusal.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum FindingRefusal {
    NoArea(FindingAreas),
    Full(FindingCount),
    NotYours(FindingHeld),
    NoFinding,
    NoGoal,
    Ended,
    Words(FindingWords),
}

// Record: FindingRefusal.
impl Record for FindingRefusal {
    type Limits = Limits;
    const TAIL: Path = paths::FINDING_REFUSAL_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2124)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2124)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::NoArea(value) => { field::put(out, &[0], paths::FINDING_REFUSAL_TAG)?; value.write(limits, out) },
            Self::Full(value) => { field::put(out, &[1], paths::FINDING_REFUSAL_TAG)?; value.write(limits, out) },
            Self::NotYours(value) => { field::put(out, &[2], paths::FINDING_REFUSAL_TAG)?; value.write(limits, out) },
            Self::NoFinding => field::put(out, &[3], paths::FINDING_REFUSAL_TAG),
            Self::NoGoal => field::put(out, &[4], paths::FINDING_REFUSAL_TAG),
            Self::Ended => field::put(out, &[5], paths::FINDING_REFUSAL_TAG),
            Self::Words(value) => { field::put(out, &[6], paths::FINDING_REFUSAL_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::FINDING_REFUSAL_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::NoArea(FindingAreas::read(limits, reader)?)),
            1 => Ok(Self::Full(FindingCount::read(limits, reader)?)),
            2 => Ok(Self::NotYours(FindingHeld::read(limits, reader)?)),
            3 => Ok(Self::NoFinding),
            4 => Ok(Self::NoGoal),
            5 => Ok(Self::Ended),
            6 => Ok(Self::Words(FindingWords::read(limits, reader)?)),
            7..=u8::MAX => Err(Problem { path: paths::FINDING_REFUSAL_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

