// Record: Value.
impl Record for Value {
    type Limits = Limits;
    const TAIL: Path = paths::VALUE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2327)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2327)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Call(value) => { field::put(out, &[0], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::ProposedEffect(value) => { field::put(out, &[1], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Repository(value) => { field::put(out, &[2], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Hold(value) => { field::put(out, &[3], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Names(value) => { field::put(out, &[4], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Subscription(value) => { field::put(out, &[5], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::BranchHead(value) => { field::put(out, &[6], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::PullState(value) => { field::put(out, &[7], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Ci(value) => { field::put(out, &[8], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Landed(value) => { field::put(out, &[9], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Entry(value) => { field::put(out, &[10], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Client(value) => { field::put(out, &[11], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Issue(value) => { field::put(out, &[12], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Release(value) => { field::put(out, &[13], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Application(value) => { field::put(out, &[14], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Writer(value) => { field::put(out, &[15], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Binding(value) => { field::put(out, &[16], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Flight(value) => { field::put(out, &[17], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Landing(value) => { field::put(out, &[18], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Receipt(value) => { field::put(out, &[19], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Forge(value) => { field::put(out, &[20], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::ForgeNumber(value) => { field::put(out, &[21], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Playground(value) => { field::put(out, &[22], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Tier(value) => { field::put(out, &[23], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Verification(value) => { field::put(out, &[24], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Setting(value) => { field::put(out, &[25], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Dismissed(value) => { field::put(out, &[26], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Making(value) => { field::put(out, &[27], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::LandingLog(value) => { field::put(out, &[28], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::ProjectFacts(value) => { field::put(out, &[29], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Looked(value) => { field::put(out, &[30], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Away(value) => { field::put(out, &[31], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Decided(value) => { field::put(out, &[32], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Closer(value) => { field::put(out, &[33], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::LandedDraft(value) => { field::put(out, &[34], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Follow(value) => { field::put(out, &[35], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Device(value) => { field::put(out, &[36], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Finding(value) => { field::put(out, &[37], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::HistoryProject(value) => { field::put(out, &[38], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::HistoryEvent(value) => { field::put(out, &[39], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::HistoryChange(value) => { field::put(out, &[40], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::HistoryLanding(value) => { field::put(out, &[41], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::HistoryLast(value) => { field::put(out, &[42], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Red(value) => { field::put(out, &[43], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::RedNumber(value) => { field::put(out, &[44], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::RedPass(value) => { field::put(out, &[45], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::ChangeCold(value) => { field::put(out, &[46], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::ChangeHot(value) => { field::put(out, &[47], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Milestone(value) => { field::put(out, &[48], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::PersonBrief(value) => { field::put(out, &[49], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::LimitHold(value) => { field::put(out, &[50], paths::VALUE_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::VALUE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Call(Call::read(limits, reader)?)),
            1 => Ok(Self::ProposedEffect(ProposedEffect::read(limits, reader)?)),
            2 => Ok(Self::Repository(Adopted::read(limits, reader)?)),
            3 => Ok(Self::Hold(Hold::read(limits, reader)?)),
            4 => Ok(Self::Names(Names::read(limits, reader)?)),
            5 => Ok(Self::Subscription(Subscriber::read(limits, reader)?)),
            6 => Ok(Self::BranchHead(BranchHead::read(limits, reader)?)),
            7 => Ok(Self::PullState(PullState::read(limits, reader)?)),
            8 => Ok(Self::Ci(CiState::read(limits, reader)?)),
            9 => Ok(Self::Landed(Landed::read(limits, reader)?)),
            10 => Ok(Self::Entry(EntryRow::read(limits, reader)?)),
            11 => Ok(Self::Client(ClientRow::read(limits, reader)?)),
            12 => Ok(Self::Issue(Box::new(IssueRow::read(limits, reader)?))),
            13 => Ok(Self::Release(ReleaseRow::read(limits, reader)?)),
            14 => Ok(Self::Application(Application::read(limits, reader)?)),
            15 => Ok(Self::Writer(ForgeWriter::read(limits, reader)?)),
            16 => Ok(Self::Binding(Binding::read(limits, reader)?)),
            17 => Ok(Self::Flight(Flight::read(limits, reader)?)),
            18 => Ok(Self::Landing(Box::new(LandingRow::read(limits, reader)?))),
            19 => Ok(Self::Receipt(ReceiptRow::read(limits, reader)?)),
            20 => Ok(Self::Forge(Forge::read(limits, reader)?)),
            21 => Ok(Self::ForgeNumber(ForgeNumber::read(limits, reader)?)),
            22 => Ok(Self::Playground(Playground::read(limits, reader)?)),
            23 => Ok(Self::Tier(Box::new(TierRow::read(limits, reader)?))),
            24 => Ok(Self::Verification(Verification::read(limits, reader)?)),
            25 => Ok(Self::Setting(SettingRow::read(limits, reader)?)),
            26 => Ok(Self::Dismissed(Dismissed::read(limits, reader)?)),
            27 => Ok(Self::Making(RepositoryMaking::read(limits, reader)?)),
            28 => Ok(Self::LandingLog(LandingLog::read(limits, reader)?)),
            29 => Ok(Self::ProjectFacts(ProjectFacts::read(limits, reader)?)),
            30 => Ok(Self::Looked(Looked::read(limits, reader)?)),
            31 => Ok(Self::Away(Away::read(limits, reader)?)),
            32 => Ok(Self::Decided(Decided::read(limits, reader)?)),
            33 => Ok(Self::Closer(Closer::read(limits, reader)?)),
            34 => Ok(Self::LandedDraft(LandedDraft::read(limits, reader)?)),
            35 => Ok(Self::Follow(Box::new(FollowRow::read(limits, reader)?))),
            36 => Ok(Self::Device(Device::read(limits, reader)?)),
            37 => Ok(Self::Finding(Finding::read(limits, reader)?)),
            38 => Ok(Self::HistoryProject(HistoryProject::read(limits, reader)?)),
            39 => Ok(Self::HistoryEvent(HistoryEvent::read(limits, reader)?)),
            40 => Ok(Self::HistoryChange(HistoryChange::read(limits, reader)?)),
            41 => Ok(Self::HistoryLanding(HistoryLanding::read(limits, reader)?)),
            42 => Ok(Self::HistoryLast(HistoryLast::read(limits, reader)?)),
            43 => Ok(Self::Red(Red::read(limits, reader)?)),
            44 => Ok(Self::RedNumber(RedNumber::read(limits, reader)?)),
            45 => Ok(Self::RedPass(RedPass::read(limits, reader)?)),
            46 => Ok(Self::ChangeCold(Box::new(ChangeCold::read(limits, reader)?))),
            47 => Ok(Self::ChangeHot(Box::new(ChangeHot::read(limits, reader)?))),
            48 => Ok(Self::Milestone(MilestoneRow::read(limits, reader)?)),
            49 => Ok(Self::PersonBrief(PersonBrief::read(limits, reader)?)),
            50 => Ok(Self::LimitHold(LimitHold::read(limits, reader)?)),
            51..=u8::MAX => Err(Problem { path: paths::VALUE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

// Type: Row.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Row {
    pub value: Value,
}

// Record: Row.
impl Record for Row {
    type Limits = Limits;
    const TAIL: Path = paths::ROW_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2328)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 2328)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::put(out, &VERSION.to_be_bytes(), paths::ROW_VERSION)?;
        field::write(field::Nested, &self.value, limits, out, paths::ROW_VALUE)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        field::version(reader, VERSION, paths::ROW_VERSION)?;
        Ok(Self {
            value: field::read(field::Nested, limits, reader, paths::ROW_VALUE)?,
        })
    }
}

